    q = 8
    p = 3  # 3/8 turn -> delta = theta * 3/8 = (2pi*R/L) * 3/8 = (3/8) * (3/2) pi = 9/16 pi
    theta = 2 * math.pi * R / L
    frac = min(p/q, 1 - p/q)
    delta = theta * frac
    s = 720
    t = 715
