    Bx, By = t * math.cos(delta), t * math.sin(delta)
    vx, vy = Bx - Ax, By - Ay
    denom = vx*vx + vy*vy
    dot = Ax * vx + Ay * vy
    u_star = -dot / denom
    cross = abs(Ax * By - Ay * Bx)
    r_line = cross / math.sqrt(denom)
    a = int(r_line + 20)
    ans = {
        'base_radius': R,
        'height': H,
        'inner_slant': a,
        'slant_start': s,
        'slant_end': t,
        'p': p,
        'q': q
    }
