# Validate and compute least path length on a truncated cone (frustum) surface
import math
try:
    R = assign['base_radius']
    H = assign['height']
    a = assign['inner_slant']
    s = assign['slant_start']
    t = assign['slant_end']
    p = assign['p']
    q = assign['q']
except Exception:
    # Missing keys
    return (False, None)
# Basic domain checks
if not (isinstance(R, (int, float)) and isinstance(H, (int, float)) and isinstance(a, (int, float)) and isinstance(s, (int, float)) and isinstance(t, (int, float)) and isinstance(p, int) and isinstance(q, int)):
    # Wrong types
    return (False, None)
if R <= 0 or H <= 0:
    # Invalid cone
    return (False, None)
L = math.sqrt(R*R + H*H)
if a <= 0 or a >= L:
    # Invalid inner slant cutoff
    return (False, None)
if s < a or t < a or s > L or t > L:
    # Points not on frustum lateral band
    return (False, None)
if q <= 1 or p <= 0 or p >= q:
    # Invalid fraction
    return (False, None)
# Compute minimal effective angular separation in the developed sector
theta = 2 * math.pi * R / L
frac = min(p/q, 1 - p/q)
delta = theta * frac
if not (delta > 0):
    # Nontrivial separation required
    return (False, None)
# For difficulty, avoid trivial tiny separations
if delta < 0.15 * theta:
    # Too easy / trivial wrap
    return (False, None)
# Geometry in the plane for one optimally chosen sector copy
Ax, Ay = s, 0.0
Bx, By = t * math.cos(delta), t * math.sin(delta)
vx, vy = Bx - Ax, By - Ay
denom = vx*vx + vy*vy
if denom == 0:
    return (False, None)
dot = Ax * vx + Ay * vy
u_star = -dot / denom
cross = abs(Ax * By - Ay * Bx)
r_line = cross / math.sqrt(denom)
# Minimal radius along the segment
if 0.0 <= u_star <= 1.0:
    r_min = r_line
else:
    r_min = min(s, t)
# Margin to enforce difficulty (avoid borderline equalities)
margin = max(10.0, 0.02 * L)
# Decide case and compute length
if r_min >= a + 1e-9:
    # Straight chord permitted
    # Enforce nontriviality: ensure comfortably outside the cutoff
    if r_min < a + 0.5 * margin:
        # borderline -> reject
        return (False, None)
    d = math.sqrt(max(s*s + t*t - 2*s*t*math.cos(delta), 0.0))
    return (True, d)
else:
    # Straight chord hits forbidden inner disk: tangent-arc-tangent path
    if r_min > a - 0.5 * margin:
        # borderline -> reject
        return (False, None)
    # Tangent angles
    if not (a <= s and a <= t):
        return (False, None)
    # Guard against numerical issues: a/s, a/t in [-1,1]
    x1 = max(-1.0, min(1.0, a / s))
    x2 = max(-1.0, min(1.0, a / t))
    gamma_s = math.acos(x1)
    gamma_t = math.acos(x2)
    phi = delta - (gamma_s + gamma_t)
    if phi <= 0:
        # If phi <= 0, tangent construction contradicts chord intersection; reject to be safe
        return (False, None)
    d = math.sqrt(max(s*s - a*a, 0.0)) + math.sqrt(max(t*t - a*a, 0.0)) + a * phi
    return (True, d)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

